mapper.select:
SELECT COUNT(1) FROM (
    SELECT canonical_symbol, trade_date FROM mdf_dataset_version_manifest
    WHERE dataset_version_id = #{datasetVersionId}
    GROUP BY canonical_symbol, trade_date HAVING COUNT(1) > 1
) duplicated

SELECT COUNT(1) FROM mdf_dataset_version_manifest m JOIN stock_daily_bar b ON b.id = m.bar_id WHERE m.dataset_version_id = #{datasetVersionId}
AND (DAYOFWEEK(m.trade_date) IN (1, 7) OR NOT EXISTS ( SELECT 1 FROM market_calendar c WHERE c.market_code = #{marketCode} AND c.trade_date = m.trade_date AND c.is_trading_day = TRUE))
AND DAYOFWEEK(m.trade_date) IN (1, 7)

SELECT MAX(b.fetched_at) FROM mdf_dataset_version_manifest m
JOIN stock_daily_bar b ON b.id = m.bar_id
WHERE m.dataset_version_id = #{datasetVersionId}
